  s.jobs.ClearForDay();Check(CompleteFixtureRide(s),"complete a real settled ride for immediate reaccept fixture");int completed=s.jobs.completed,passengers=s.business.passengers.Count,cashBefore=s.business.ledger.Account.Cash;Check(m.Open(),"open map during completion transient");bool selected=false;for(int i=0;i<s.jobs.offers.Length;i++)if(m.SelectOffer(i)&&m.AcceptBlockedReason==""){selected=true;break;}Check(selected&&m.AcceptSelected()&&s.jobs.Active&&!m.IsOpen&&Time.timeScale>0,"settled ride immediately accepts next call while map clock is frozen");Check(s.jobs.completed==completed&&s.business.passengers.Count==passengers&&s.business.ledger.Account.Cash==cashBefore,"next acceptance does not settle previous ride twice");s.jobs.ClearForDay();
