 static void AtStop(DriveSession s,int index){var stop=s.jobs.stops[index];s.taxi.SetSpawn(stop.Kerb+Vector3.up*.65f,Quaternion.LookRotation(stop.Direction));s.taxi.ResetTaxi();}
 static bool CompleteFixtureRide(DriveSession s){s.jobs.ForcedRideCase=DrunkRideCase.Normal;int index=Array.FindIndex(s.jobs.offers,o=>o!=null);if(index<0||!s.jobs.Accept(index))return false;AtStop(s,s.jobs.current.pickup);if(!s.jobs.Interact())return false;AtStop(s,s.jobs.current.drop);return s.jobs.Interact()&&s.jobs.trip.State==TripState.Complete;}
 [Serializable] sealed class ClickState {public string phase,trip,reason;public int clicks,selected;public bool mapOpen,paused;public float timeScale,x,y,width,height;}
 void WriteClickState(FullMapOverlay map,DriveSession s,string phase){var r=map.AcceptButtonBounds;var state=new ClickState{phase=phase,trip=s.jobs.trip.State.ToString(),reason=map.AcceptFeedback,clicks=map.AcceptButtonClickCount,selected=map.SelectedOffer,mapOpen=map.IsOpen,paused=s.paused,timeScale=Time.timeScale,x=r.x,y=r.y,width=r.width,height=r.height};string path=System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../../..","artifacts","map-click-test.json"));System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(path));System.IO.File.WriteAllText(path,JsonUtility.ToJson(state,true));Debug.Log("MAP_GUI_CLICK_"+phase.ToUpperInvariant()+" "+JsonUtility.ToJson(state));}
 IEnumerator MouseClickFixture(DriveSession s,FullMapOverlay map){bool after=Array.IndexOf(Environment.GetCommandLineArgs(),"-mapClickAfterSettlement")>=0;if(after)Check(CompleteFixtureRide(s),"GUI fixture settles previous ride");Check(map.Open(),"GUI click fixture opens map");bool selected=false;for(int i=0;i<s.jobs.offers.Length;i++)if(map.SelectOffer(i)&&map.AcceptBlockedReason==""){selected=true;break;}Check(selected,"GUI fixture selects a reachable call");yield return new WaitForSecondsRealtime(.3f);WriteClickState(map,s,"ready");ScreenCapture.CaptureScreenshot(System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../../..","artifacts","map-click-ready.png")));float until=Time.realtimeSinceStartup+90;while(Time.realtimeSinceStartup<until&&map.AcceptButtonClickCount==0)yield return null;Check(map.AcceptButtonClickCount==1&&s.jobs.Active&&!map.IsOpen&&!s.paused&&Time.timeScale>0,"actual GUI.Button click accepts selected call and resumes driving");WriteClickState(map,s,ok?"passed":"failed");Application.Quit(ok?0:1);}
